CREATE INDEX idx_announcement_reads_seen ON public.announcement_reads USING btree (seen_at DESC);
CREATE INDEX assignments_hedef ON public.assignments USING btree (class_no, branch) WHERE active;
CREATE INDEX idx_audit_logs_created ON public.audit_logs USING btree (created_at DESC);
CREATE INDEX idx_chat_messages_student ON public.chat_messages USING btree (student_id, created_at);
CREATE INDEX dm_break_daily ON public.dm_break_runs USING btree (student_id, day, game);
CREATE INDEX dm_break_best ON public.dm_break_runs USING btree (game, score DESC, student_id) WHERE (status = 'finished'::text);
CREATE INDEX dm_email_student_time ON public.dm_email_verifications USING btree (student_id, created_at);
CREATE INDEX dm_topic_game_daily ON public.dm_game_reward_runs USING btree (student_id, topic_key, game_key, created_at) WHERE (game_key ~~ 'konu:%'::text);
CREATE INDEX dm_game_reward_cooldown_idx ON public.dm_game_reward_runs USING btree (student_id, game_key, class_no, created_at DESC);
CREATE INDEX dm_guardian_challenges_student ON public.dm_guardian_challenges USING btree (student_id, created_at DESC);
CREATE INDEX dm_guardian_sessions_student ON public.dm_guardian_sessions USING btree (student_id);
CREATE INDEX dm_lesson_fair_runs_topic ON public.dm_lesson_fair_runs USING btree (student_id, level, category, topic_name);
CREATE INDEX dm_matches_b ON public.dm_matches USING btree (player_b, created_at DESC);
CREATE INDEX dm_matches_a ON public.dm_matches USING btree (player_a, created_at DESC);
CREATE INDEX dm_oral_teacher_history ON public.dm_oral_questions USING btree (teacher_id, created_at DESC);
CREATE INDEX dm_papi_chat_global_day ON public.dm_papi_chat_turns USING btree (global_day, student_id);
CREATE INDEX dm_papi_chat_personal_day ON public.dm_papi_chat_turns USING btree (student_id, personal_day, created_at);
CREATE UNIQUE INDEX dm_papi_routine_email_once_future ON public.dm_papi_progress_outbox USING btree (lower(btrim(to_email)), kind, report_date) WHERE ((report_date > '2026-10-18'::date) AND (kind = ANY (ARRAY['papi_progress'::text, 'papi_league_sunday'::text, 'papi_league_monday'::text])));
CREATE INDEX dm_papi_outbox_due ON public.dm_papi_progress_outbox USING btree (send_after) WHERE ((sent_at IS NULL) AND (attempts < 5));
CREATE UNIQUE INDEX dm_papi_league_email_once_future ON public.dm_papi_progress_outbox USING btree (lower(btrim(to_email)), kind, report_date) WHERE ((kind ~~ 'papi_league_%'::text) AND (report_date > '2026-10-18'::date));
CREATE UNIQUE INDEX dm_papi_progress_outbox_unique ON public.dm_papi_progress_outbox USING btree (student_id, recipient_kind, lower(to_email), report_date, kind);
CREATE INDEX dm_password_resets_student ON public.dm_password_resets USING btree (student_id);
CREATE INDEX dm_progress_mail_due_idx ON public.dm_progress_mail_preferences USING btree (last_queued_at) WHERE ((unsubscribed_at IS NULL) AND (opted_in_at IS NOT NULL) AND (verified_at IS NOT NULL));
CREATE INDEX dm_rally_ranking ON public.dm_rally_runs USING btree (class_no, finished_at DESC) WHERE (status = 'finished'::text);
CREATE INDEX dm_rally_history ON public.dm_rally_runs USING btree (student_id, created_at DESC);
CREATE INDEX dm_safety_reports_target ON public.dm_safety_reports USING btree (target_id, created_at DESC);
CREATE INDEX dm_safety_reports_queue ON public.dm_safety_reports USING btree (status, created_at DESC);
CREATE INDEX dm_teacher_student_notices_unread ON public.dm_teacher_student_notices USING btree (student_id, created_at) WHERE (acknowledged_at IS NULL);
CREATE INDEX dm_notices_teacher_appeals_idx ON public.dm_teacher_student_notices USING btree (teacher_id, appealed_at DESC) WHERE (appealed_at IS NOT NULL);
CREATE INDEX dm_thematic_enrollment_student ON public.dm_thematic_enrollment USING btree (student_id);
CREATE INDEX dm_thematic_enrollment_teacher ON public.dm_thematic_enrollment USING btree (teacher_id);
